import binascii
def key_slot(key: bytes) -> int:
    s = key.find(b"{")
    if s != -1:
        e = key.find(b"}", s + 1)
        if e > s + 1:
            key = key[s + 1:e]          # hash tag: only the part inside {}
    return binascii.crc_hqx(key, 0) % 16384   # CRC16-CCITT (XMODEM), as Redis Cluster uses

