def _flush_replication(self) -> None:
    self._repl_flush_scheduled = False
    if not self._repl_pending:
        return
    chunk = b"".join(self._repl_pending)
    self._repl_pending.clear()
    for r in list(self.replicas.values()):
        r.writer.write(chunk)

